import catalog from '../../src/data/catalog.json';import variants from '../../src/data/report-variants.json';import samples from './measurements.json';import {ReportEngine} from '../../src/engine/client.ts';
import type {EngineJob} from '../../src/engine/client.ts';
const digest=async(bytes:Uint8Array)=>[...new Uint8Array(await crypto.subtle.digest('SHA-256',new Uint8Array(bytes).buffer))].map(n=>n.toString(16).padStart(2,'0')).join('');
async function documentXml(bytes:Uint8Array){const view=new DataView(bytes.buffer,bytes.byteOffset,bytes.byteLength);let end=bytes.length-22;while(end>=0&&view.getUint32(end,true)!==0x06054b50)end--;if(end<0)throw Error('ZIP missing');let offset=view.getUint32(end+16,true);for(let i=0;i<view.getUint16(end+10,true);i++){const size=view.getUint16(offset+28,true),name=new TextDecoder().decode(bytes.slice(offset+46,offset+46+size));if(name==='word/document.xml'){const local=view.getUint32(offset+42,true),start=local+30+view.getUint16(local+26,true)+view.getUint16(local+28,true),payload=bytes.slice(start,start+view.getUint32(offset+20,true));return new TextDecoder().decode(view.getUint16(offset+10,true)===0?payload:await new Response(new Blob([new Uint8Array(payload).buffer]).stream().pipeThrough(new DecompressionStream('deflate-raw'))).arrayBuffer());}offset+=46+size+view.getUint16(offset+30,true)+view.getUint16(offset+32,true);}throw Error('Document missing');}
export async function verifyRuntimeReuse(progress:(value:unknown)=>void,contextCases=false){
 const exps=contextCases?catalog.experiments.filter(e=>/直螺线管|理想气体|静电场/.test(e.sourceId)):catalog.experiments;
 const original=window.Worker;let created=0,live=0,max=0;window.Worker=class extends original {private dead=false;constructor(url:string|URL,options?:WorkerOptions){super(url,options);created++;max=Math.max(max,++live);}terminate(){if(!this.dead){this.dead=true;live--;}super.terminate();}};
 const documents=new Map<string,string>();
 const baseline=new ReportEngine(async()=>null),reused=new ReportEngine(async()=>null,true,true),rows:{id:string;xmlHash:string;chartHashes:string[];formulas:number;ms:number}[][]=[[],[]];
 try{for(let phase=0;phase<2;phase++)for(const exp of exps){const start=performance.now(),name='profile_'+exp.id,job:EngineJob&{seed:number}={experimentId:exp.id,data:(samples as any)[exp.id],profile:{name,studentId:'00'+exp.id,className:phase?'same class':'same class'},date:'2026-10-27',seed:42,options:{variants:Object.fromEntries(Object.keys((variants as any)[exp.id]).map(k=>[k,0]))}};if(phase&&contextCases){const context=await reused.calculate({...job,profile:{name:'',studentId:'',className:''}},()=>{});if(context.experimentId!==exp.id)throw Error('Calculation context leaked')}const result=await(phase?reused:baseline).generate(job as Omit<EngineJob,'mode'>,()=>{}),xml=await documentXml(result.docx);if(!xml.includes(name))throw Error('Profile leaked: '+exp.id);const row={id:exp.id,xmlHash:await digest(new TextEncoder().encode(xml)),chartHashes:await Promise.all(result.charts.map(c=>digest(c.bytes))),formulas:result.metadata.formulaCount,ms:performance.now()-start};rows[phase].push(row);if(!phase)documents.set(exp.id,xml);if(phase){const before=rows[0].find(r=>r.id===exp.id)!;if(row.xmlHash!==before.xmlHash||row.formulas!==before.formulas||JSON.stringify(row.chartHashes)!==JSON.stringify(before.chartHashes)){(window as any).reuseMismatch={id:exp.id,name:exp.name,before,row,baselineXml:documents.get(exp.id),reusedXml:xml};throw Error('Report changed with reuse: '+exp.id);}}progress({phase:phase?'reused':'fresh',completed:rows[phase].length,ms:row.ms,workersCreated:created});}
 reused.releaseIdle();if(live!==0||max!==1||created!==exps.length+1)throw Error('Runtime lifetime incorrect: '+JSON.stringify({live,max,created}));return {rows,created,max,live,exactDocumentXmlMatches:exps.length,contextCases,exactChartBytesMatch:true};
 }finally{baseline.cancel();reused.cancel();window.Worker=original;}
}
